class Solution:
    def countDistinctStrings(self, s: str, k: int) -> int:
        n = len(s); starts = n - k + 1
        seen = set()
        for mask in range(1 << starts):
            arr = list(s)
            for i in range(starts):
                if mask >> i & 1:
                    for j in range(i, i + k):
                        arr[j] = '0' if arr[j] == '1' else '1'
            seen.add(''.join(arr))
        return len(seen) % (10**9 + 7)

