class Solution {
public:
    int countDistinctStrings(string s, int k) {
        int n = s.size(), starts = n - k + 1;
        unordered_set<string> seen;
        for (int mask = 0; mask < (1 << starts); mask++) {
            string t = s;
            for (int i = 0; i < starts; i++)
                if (mask >> i & 1)
                    for (int j = i; j < i + k; j++) t[j] ^= 1;
            seen.insert(t);
        }
        return seen.size() % 1000000007;
    }
};

