var countDistinctStrings = function(s, k) {
    const n = s.length, starts = n - k + 1, seen = new Set();
    for (let mask = 0; mask < (1 << starts); mask++) {
        const t = s.split('');
        for (let i = 0; i < starts; i++)
            if (mask >> i & 1)
                for (let j = i; j < i + k; j++) t[j] = t[j] === '0' ? '1' : '0';
        seen.add(t.join(''));
    }
    return seen.size % 1000000007;
};

