class Solution {
public:
    int countDistinctStrings(string s, int k) {
        long long b = 2, e = s.size() - k + 1, r = 1, MOD = 1e9 + 7;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
};

