class Solution {
    public int countDistinctStrings(String s, int k) {
        long b = 2, e = s.length() - k + 1, r = 1, MOD = 1000000007L;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return (int) r;
    }
}

